package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamBioCellsBank2 {
  private const val T = "ජීවයේ රසායනික පදනම, සෛලය හා වර්ගීකරණය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ජීව විද්‍යා විෂය නිර්දේශයට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("රොබට් හුක් 1665 දී කිරළ කැබැල්ලක් අන්වීක්ෂයෙන් නිරීක්ෂණය කර දුටු හිස් කුටීර හැඳින්වීමට යෙදූ පදය කුමක්ද?", "සෛල (Cells)", "න්‍යෂ්ටිය", "පටක", "ඉන්ද්‍රයිකා", "මළ ශාක සෛල බිත්ති කුටීර ඔහු 'Cells' ලෙස නම් කළේය."),
    q("සියලුම ජීවීන් සෛලවලින් සෑදී ඇති බවත්, සෛලය ජීවයේ මූලික ඒකකය බවත් ප්‍රකාශ කෙරෙන සිද්ධාන්තය කුමක්ද?", "සෛල වාදය", "පරිණාමවාදය", "මෙන්ඩල් වාදය", "චාලක අණුක වාදය", "ෂ්ලයිඩන්, ෂ්වාන් සහ විර්චෝ සෛල වාදය ගොඩනැගූහ."),
    q("නව සෛල ඇතිවන්නේ කෙසේදැයි රුඩොල්ෆ් විර්චෝ පැහැදිලි කළේ කුමන ප්‍රකාශයෙන්ද?", "පෙර පැවති සෛල විභාජනය වීමෙනි", "අජීවී ද්‍රව්‍යවලින් ස්වයංසිද්ධවයි", "වායුගෝලීය වායූන් ඝනීභවනයෙනි", "ජලය හා ඛනිජ මිශ්‍ර වීමෙනි", "සෑම සෛලයක්ම පෙර පැවති සෛලයකින් හටගනී."),
    q("අන්වීක්ෂයකින් ඉතා කුඩා වෛරස සහ සෛලීය අභ්‍යන්තර ව්‍යුහ පැහැදිලිව නිරීක්ෂණය කිරීමට වඩාත් සුදුසු උපකරණය කුමක්ද?", "ඉලෙක්ට්‍රෝන අන්වීක්ෂය", "සරල අන්වීක්ෂය", "සංයුක්ත ආලෝක අන්වීක්ෂය", "විශාලන කාචය", "ඉලෙක්ට්‍රෝන අන්වීක්ෂයේ විභේදන බලය ඉතා ඉහළය."),
    q("සූන්‍යෂ්ටික සෛලයක ප්‍රභාසංස්ලේෂණය සිදු කරන හරිතලවයේ අභ්‍යන්තර පටලමය පද්ධතිය කුමක්ද?", "තයිලකොයිඩ", "ක්‍රිස්ටා", "ටෝනොප්ලාස්ට", "සෙන්ට්‍රියෝල", "කාසි ගොඩවල් මෙන් පිහිටි තයිලකොයිඩ කණිකා (Grana) සාදයි."),
    q("මයිටොකොන්ඩ්‍රියාවේ ඇතුළත පටලය නැමී සෑදී ඇති ව්‍යුහ හඳුන්වන්නේ කුමන නමින්ද?", "ක්‍රිස්ටා", "ග්‍රැනා", "ස්ට්‍රෝමා", "ප්ලාස්ම බන්ධ", "ක්‍රිස්ටා මඟින් ATP නිපදවීමට පෘෂ්ඨීය වර්ගඵලය වැඩි කරයි."),
    q("වැඩිපුර ශක්තිය අවශ්‍ය වන මිනිස් දේහයේ කුමන සෛලවල මයිටොකොන්ඩ්‍රියා ඉතා බහුලව පවතීද?", "හෘත් පේශි සෛල", "මේද සෛල", "අපිචර්ම මතුපිට සෛල", "රතු රුධිරාණු", "නිරන්තර සංකෝචනය සඳහා හෘත් පේශි සෛලවලට අධික ATP ප්‍රමාණයක් අවශ්‍ය වේ."),
    q("පරිණත මිනිස් රතු රුධිරාණුවක දක්නට නොලැබෙන සෛලීය ඉන්ද්‍රයිකාව කුමක්ද?", "න්‍යෂ්ටිය", "හිමොග්ලොබින්", "ප්ලාස්ම පටලය", "සෛල ප්ලාස්මය", "වැඩි ඔක්සිජන් ප්‍රමාණයක් රැගෙන යාමට රතු රුධිරාණුවල න්‍යෂ්ටිය නොමැත."),
    q("ගොවිතැනට හිතකර නයිට්‍රජන් තිර කරන බැක්ටීරියාවක් වන රයිසෝබියම් ජීවත් වන්නේ කොහේද?", "රනිල කුලයේ ශාක මූල ගැටිතිවල", "වී පත්‍ර මතුපිට", "පොල් මුල් අග්‍රයේ", "මීවන බීජාණු කෝෂවල", "රයිසෝබියම් සහ රනිල ශාක අතර අන්‍යෝන්‍යාධාර සබඳතාවක් පවතී."),
    q("අසංතෘප්ත මේද අම්ල සාමාන්‍ය කාමර උෂ්ණත්වයේදී පවතින්නේ කුමන භෞතික අවස්ථාවේද?", "ද්‍රව (තෙල්) අවස්ථාවේ", "ඝන (මේද) අවස්ථාවේ", "වායු අවස්ථාවේ", "ස්ඵටික අවස්ථාවේ", "පොල් තෙල් හා තල තෙල් වැනි ශාක ලිපිඩ බොහෝ විට අසංතෘප්ත ද්‍රව වේ."),
    q("ආහාරමය තන්තු (සෙලියුලෝස්) මිනිස් ආහාර වේලට එකතු කර ගැනීමේ ප්‍රධාන වැදගත්කම කුමක්ද?", "මලබද්ධය වැළැක්වීම", "වැඩි කැලරි ලබා ගැනීම", "ප්‍රෝටීන සංස්ලේෂණය", "රතු රුධිරාණු නිපදවීම", "තන්තු මඟින් ආහාර මාර්ගයේ ක්‍රමාකුංචන චලනය පහසු කරයි."),
    q("මිනිස් දේහයේ පරිවෘත්තීය ක්‍රියා නිසි ලෙස පවත්වා ගැනීමට ඉතා සුළු ප්‍රමාණවලින් අවශ්‍ය වන කාබනික සංයෝග මොනවාද?", "විටමින්", "කාබෝහයිඩ්‍රේට", "ලිපිඩ", "පිෂ්ඨය", "විටමින් ශක්තිය ලබා නොදුන්නද එන්සයිම ක්‍රියාකාරිත්වයට අත්‍යවශ්‍ය වේ."),
    q("පිෂ්ඨය, සෙලියුලෝස් සහ ග්ලයිකෝජන් යන පොලිසැකරයිඩ තුනේම මූලික තැනුම් ඒකකය කුමක්ද?", "ග්ලූකෝස්", "ෆ්‍රක්ටෝස්", "ගැලැක්ටෝස්", "රයිබෝස්", "මෙම බහුඅවයවික සියල්ල ග්ලූකෝස් අණු බහුඅවයවීකරණයෙන් සෑදේ."),
    q("ප්‍රෝටීන අණුවක් සෑදෙන විට ඇමයිනෝ අම්ල දෙකක් අතර සෑදෙන රසායනික බන්ධනය කුමක්ද?", "පෙප්ටයිඩ බන්ධනය", "ග්ලයිකොසිඩික් බන්ධනය", "එස්ටර බන්ධනය", "අයනික බන්ධනය", "පෙප්ටයිඩ බන්ධන සෑදීමේදී ජල අණුවක් ඉවත් වේ (සංඝනීභවන ප්‍රතික්‍රියාව)."),
    q("එන්සයිමයක් අධික උෂ්ණත්වයකට (උදාහරණයක් ලෙස 80°C) ලක් කළ විට එහි ක්‍රියාකාරිත්වය නැවතීමට හේතුව කුමක්ද?", "ප්‍රෝටීන ව්‍යුහය දුස්ස්වභාවීකරණය වීම", "උපස්තරය ජලයේ දියවීම", "pH අගය වැඩිවීම", "ATP ක්ෂය වීම", "අධික තාපය නිසා එන්සයිමයේ සක්‍රිය මධ්‍යස්ථානයේ ත්‍රිමාණ හැඩය විකෘති වේ."),
    q("විටමින් B₁ (තයමින්) ඌනතාව නිසා මිනිසාට වැළඳෙන රෝගය කුමක්ද?", "බෙරිබෙරි", "ස්කර්වි", "රිකට්ස්", "පෙලග්‍රා", "විටමින් B₁ ඌනතාව ස්නායු පද්ධතියට හා හෘදයට බලපාන බෙරිබෙරි රෝගය ඇති කරයි."),
    q("අස්ථි හා දත් ශක්තිමත් කිරීමට අත්‍යවශ්‍ය වන ප්‍රධාන ඛනිජ ලවණ යුගලය කුමක්ද?", "කැල්සියම් සහ පොස්පරස්", "යකඩ සහ අයඩින්", "සෝඩියම් සහ ක්ලෝරීන්", "මැග්නීසියම් සහ තඹ", "අස්ථි සෑදී ඇත්තේ ප්‍රධාන වශයෙන් කැල්සියම් පොස්පේට් ලවණවලිනි."),
    q("සෛලයක ආස්‍රැති පීඩනය සහ ජල සමතුලිතතාව පවත්වා ගැනීම සඳහා වැදගත් වන අයන යුගලය කුමක්ද?", "සෝඩියම් සහ පොටෑසියම්", "කැල්සියම් සහ යකඩ", "අයඩින් සහ ප්ලෝරීන්", "සින්ක් සහ තඹ", "Na⁺ හා K⁺ අයන ස්නායු ආවේග සම්ප්‍රේෂණයට ද දායක වේ."),
    q("ප්‍රෝටීන ඌනතාව නිසා කුඩා දරුවන් තුළ ඇතිවන ප්‍රධාන පෝෂණ ඌනතා රෝගය කුමක්ද?", "ක්වාෂියෝකෝර්", "ගලගණ්ඩය", "දියවැඩියාව", "රක්තහීනතාව", "ප්‍රෝටීන ඌනතාව නිසා උදරය ඉදිරියට නෙරා ඒම හා වර්ධනය අඩාල වීම සිදුවේ."),
    q("ශාක පටකයක් තුළ කැල්සියම් ඌනතාව නිසා මුලින්ම දක්නට ලැබෙන රෝග ලක්ෂණය කුමක්ද?", "අග්‍රස්ථ අංකුර මැරී යාම", "පැරණි පත්‍ර කහ වීම", "කඳේ මූල ගැටිති ඇතිවීම", "පත්‍ර දම් පැහැ ගැන්වීම", "කැල්සියම් සෛල බිත්ති තැනීමට අවශ්‍ය නිසා වැඩෙන අග්‍රවලට දැඩිව බලපායි."),
    q("ශාකවල පොස්පරස් ඌනතාව නිසා පත්‍රවල දක්නට ලැබෙන විශේෂ වර්ණ විපර්යාසය කුමක්ද?", "රතු-දම් පැහැති පැල්ලම් ඇතිවීම", "තද කොළ පැහැ වීම", "සුදු පැහැති ලප ඇතිවීම", "තැඹිලි පැහැ වීම", "පොස්පරස් ඌනතාව නිසා මූල වර්ධනය ද දුර්වල වේ."),
    q("බැක්ටීරියාවල සෛල බිත්තිය තැනී ඇති ප්‍රධාන රසායනික සංඝටකය කුමක්ද?", "පෙප්ටිඩොග්ලයිකෑන්", "සෙලියුලෝස්", "කයිටින්", "ලිග්නින්", "බැක්ටීරියා සෛල බිත්ති සෙලියුලෝස්වලින් තොර පෙප්ටිඩොග්ලයිකෑන් ස්තරයකි."),
    q("යූග්ලීනා නම් ප්‍රොටිස්ටා ජීවියා සතු සුවිශේෂී ලක්ෂණය කුමක්ද?", "හරිතප්‍රද හා කෂිකාවක් පිහිටීම", "සෛල බිත්තියක් තිබීම", "බහුසෛලික දේහයක් තිබීම", "බීජාණු මඟින් බෝවීම", "යූග්ලීනා ආලෝකය ඇති විට ප්‍රභාසංස්ලේෂණය කරයි."),
    q("පාසි හා හරිත දිය සෙවෙල් වැනි බ්‍රයොෆයිටා ශාකවල මුල් වෙනුවට පවතින ව්‍යුහය කුමක්ද?", "මූලාභ (Rhizoids)", "කේශ මූල", "කඳු මුල්", "වායව මුල්", "බ්‍රයොෆයිටා ශාක තෙත් සෙවණැති පරිසරවල වැඩේ."),
    q("මීවන ශාකයක (උදා: නෙෆ්‍රොලෙපිස්) පත්‍ර යටි පැත්තේ පිහිටි බීජාණුධානි සමූහ හඳුන්වන්නේ කුමන නමින්ද?", "බීජාණු පුංජ (Sori)", "රේණු", "කෝණ", "පුෂ්ප මංජරි", "බීජාණු පුංජ තුළින් බීජාණු විසිරී යයි."),
    q("රක්තාලේප රහිත අනූනන විභාජනය මගින් ශාකයක සිදුවන ප්‍රධාන ක්‍රියාවලිය කුමක්ද?", "දේහ වර්ධනය", "ජන්මාණු නිපදවීම", "බීජාණු නිපදවීම", "විවිධත්වය ඇති කිරීම", "අනූනන විභාජනයෙන් වර්ධනය හා ක්ෂය වූ සෛල ප්‍රතිස්ථාපනය සිදුවේ."),
    q("මිනිස් දේහයේ පිහිටි කාටිලේජ පටකයට උදාහරණයක් නොවන්නේ කුමක්ද?", "හිස්කබල", "බාහිර කණ", "නාසයේ අග්‍රය", "ශ්වාසනාල මුදු", "හිස්කබල තද අස්ථි පටකයකින් සෑදී ඇත."),
    q("සත්ව දේහයක ආවරණ පටකයක් ලෙස ක්‍රියා කරන පටක කාණ්ඩය කුමක්ද?", "අපිච්ඡද පටකය", "සම්බන්ධක පටකය", "පේශි පටකය", "ස්නායු පටකය", "සම සහ අභ්‍යන්තර අවයවවල ආස්තරණය අපිච්ඡද පටකයෙන් සෑදී ඇත."),
    q("සජීවී සෛලයක සෛල බිත්ති දෙකක් හරහා යාබද සෛල ප්ලාස්ම එකිනෙක සම්බන්ධ කරන සියුම් නාලිකා මොනවාද?", "ප්ලාස්ම බන්ධ", "ටෝනොප්ලාස්ට", "විභාජක", "කේන්ද්‍රිකා", "ප්ලාස්ම බන්ධ හරහා යාබද ශාක සෛල අතර ද්‍රව්‍ය හුවමාරු වේ."),
    q("සත්ව සෛලයක සෛල ප්ලාස්ම බෙදීම (සයිටොකයිනේසිසය) සිදුවන්නේ කෙසේද?", "ප්ලාස්ම පටලය ඇතුළට හැකිලීමෙන්", "මධ්‍යයේ සෛල තැටියක් සෑදීමෙන්", "න්‍යෂ්ටිය පුපුරා යාමෙන්", "සෛල බිත්තිය දියවීමෙන්", "ශාක සෛලවල සෛල තැටියක් සෑදෙන අතර සත්ව සෛලවල ඇතුළට හැකිලීමක් සිදුවේ."),
    q("අනූනන විභාජනයේ කුමන අවධියේදී සහෝදර වර්ණදේහාංශ (Chromatids) දෙපස ධ්‍රැව කරා ඇදී යාම සිදුවේද?", "වියෝග කලාව (Anaphase)", "ප්‍රාක් කලාව (Prophase)", "යෝග කලාව (Metaphase)", "අන්ත කලාව (Telophase)", "තර්කු තන්තු කෙටි වීම නිසා වර්ණදේහාංශ ධ්‍රැව වෙත ගමන් කරයි."),
    q("ජීවීන් අතරින් තමාගේම ආහාර නිපදවා ගැනීමට නොහැකි විෂමපෝෂී ජීවීන් අයත් වන්නේ කුමන රාජධානිවලටද?", "ෆන්ගයි සහ ඇනිමාලියා", "ප්ලාන්ටේ සහ ෆන්ගයි", "ප්ලාන්ටේ සහ ප්‍රොටිස්ටා", "මොනේරා සහ ප්ලාන්ටේ", "දිලීර හා සතුන් තුළ හරිතප්‍රද නොමැති බැවින් විෂමපෝෂී වේ."),
    q("සර්පයන් සහ ඉබ්බන් අයත් වන පෘෂ්ඨවංශී වර්ගය කුමක්ද?", "රෙප්ටීලියා", "ඇම්ෆිබියා", "පිසේස්", "මැමේලියා", "රෙප්ටීලියාවන්ට කොරපොතු සහිත වියළි සමක් ඇත."),
    q("පක්ෂීන්ගේ (ආවේස්) අස්ථිවල පියෑඹීම සඳහා ඇති ප්‍රධාන අනුවර්තනය කුමක්ද?", "වාතය පිරි සැහැල්ලු කුහරමය අස්ථි", "ඝන බරැති අස්ථි", "කාටිලේජමය පියාපත්", "සන්ධි රහිත කශේරුව", "වාත අවකාශ සහිත අස්ථි නිසා දේහ බර අඩු වේ."),
    q("මත්ස්‍යයන්ගේ ජලයේ පිහිනීමට හා සමතුලිතතාව රැක ගැනීමට උපකාරී වන අභ්‍යන්තර අවයවය කුමක්ද?", "වාතාශය (Swim bladder)", "පෙනහැලි", "ප්‍රාචීරය", "ගලනාලය", "අස්ථිමය මසුන්ගේ වාතාශය උත්ප්ලාවකතාව පාලනය කරයි."),
    q("ශ්‍රී ලංකාවට ආවේණික පක්ෂියෙකු වන්නේ කවුද?", "ශ්‍රී ලංකා වළි කුකුළා", "කපුටා", "මයිනා", "පරෙවියා", "වළි කුකුළා සහ කැහිබෙල්ලා ශ්‍රී ලංකාවට ආවේණික පක්ෂීන් වේ."),
    q("ශ්‍රී ලංකාවට ආවේණික ක්ෂීරපායී සත්වයෙකු වන්නේ කවුද?", "ශ්‍රී ලංකා උණහපුළුවා", "මුවා", "අලියා", "වල් ඌරා", "රත් පැහැ උණහපුළුවා හා කළු වඳුරා ශ්‍රී ලංකාවට ආවේණික වේ."),
    q("වී, පොල් සහ තෘණ කුලයේ ශාක පුෂ්පවල බහුලව දක්නට ලැබෙන පුෂ්ප කොටස් ගුණාකාරය කීයද?", "තුනේ ගුණාකාර (ත්‍රිඅංගික)", "පහේ ගුණාකාර", "හතේ ගුණාකාර", "දෙකේ ගුණාකාර", "ඒකබීජ පත්‍රී පුෂ්ප ත්‍රිඅංගික වේ."),
    q("සපුෂ්ප ශාක අතරින් පංචාංගික පුෂ්ප හා ජාලාභ නාරටි වින්‍යාසය පෙන්වන ශාක කාණ්ඩය කුමක්ද?", "ද්විබීජ පත්‍රී ශාක", "ඒකබීජ පත්‍රී ශාක", "විවෘත බීජ ශාක", "මීවන ශාක", "වද, කොස්, අඹ ද්විබීජ පත්‍රී ශාක වේ."),
    q("සෛලයේ සියලු ඉන්ද්‍රයිකා රඳවා ඇති ජෙලි වැනි අර්ධ ද්‍රව මාධ්‍යය කුමක්ද?", "සෛල ප්ලාස්මය", "න්‍යෂ්ටි රසය", "සෛල යුෂය", "පටක තරලය", "බොහෝ ජෛව රසායනික ප්‍රතික්‍රියා සෛල ප්ලාස්මයේ සිදුවේ."),
    q("සජීවී සෛල ප්ලාස්මයේ සෛලීය අපද්‍රව්‍ය හා ආහාර අංශු ජීර්ණය සඳහා විශේෂිත වූ ඉන්ද්‍රයිකාව කුමක්ද?", "ලයසොසෝමය", "හරිතලවය", "කේන්ද්‍රදේහය", "න්‍යෂ්ටිකාව", "ලයසොසෝම ගෙවී ගිය ඉන්ද්‍රයිකා ද විනාශ කරයි."),
    q("DNA වල අඩංගු වන පෙන්ටෝස් සීනි වර්ගය කුමක්ද?", "ඩීඔක්සිරයිබෝස්", "රයිබෝස්", "ග්ලූකෝස්", "ෆ්‍රක්ටෝස්", "RNA වල අඩංගු වන්නේ රයිබෝස් සීනි වේ."),
    q("DNA අණුවක ඇඩිනීන් (A) භෂ්මය සැමවිටම හයිඩ්‍රජන් බන්ධනවලින් යුගලනය වන්නේ කුමන භෂ්මය සමඟද?", "තයිමින් (T)", "සයිටොසීන් (C)", "ගුවැනීන් (G)", "යුරැසිල් (U)", "A=T සහ G≡C ලෙස අනුපූරක භෂ්ම යුගලනය වේ."),
    q("මිනිසාගේ දේහයේ උපත්තියේදී වර්ධනය සම්පූර්ණ වී පසුව අනූනන විභාජනය නොවන තරම් වූ සෛල වර්ගය කුමක්ද?", "ස්නායු සෛල", "අපිචර්ම සෛල", "ඇට මිදුළු සෛල", "අක්මා සෛල", "පරිණත නියුරෝන විභාජනය නොවන බැවින් හානි වූ විට ප්‍රතිස්ථාපනය අපහසුය."),
    q("මේද ජලය සමඟ මිශ්‍ර නොවීමට හේතුව කුමක්ද?", "ලිපිඩ නිර්ධ්‍රැවීය ජලභීතික සංයෝග වීම", "ලිපිඩ ජලයට වඩා ඝනත්වය වැඩි වීම", "ලිපිඩ අයනික සංයෝග වීම", "ලිපිඩ අණු කුඩා වීම", "ලිපිඩ කාබනික ද්‍රාවකවල (ඊතර්, බෙන්සීන්) දියවේ."),
    q("ප්‍රෝටීන විශාල ප්‍රමාණයක් අඩංගු ශාකමය ආහාර ප්‍රභවයකට උදාහරණයක් වන්නේ කුමක්ද?", "සෝයා බෝංචි", "බතල", "අල", "කෙසෙල්", "රනිල බෝගවල (සෝයා, මුං, පරිප්පු) ශාක ප්‍රෝටීන බහුලය."),
    q("කාබෝහයිඩ්‍රේට බහුලව අඩංගු ආහාර වර්ගයක් වන්නේ කුමක්ද?", "බත්", "මස්", "බිත්තර සුදු මදය", "වෙඬරු", "ධාන්‍ය හා අල වර්ගවල පිෂ්ඨය බහුලව අඩංගු වේ."),
    q("සජීවී දේහවල අවයව ආරක්ෂා කිරීමේ කම්පන අවශෝෂකයක් ලෙසත්, තාප පරිවාරකයක් ලෙසත් ක්‍රියා කරන්නේ කුමක්ද?", "මේද ස්තරය", "පිෂ්ඨය", "ඛනිජ ලවණ", "න්‍යෂ්ටික අම්ල", "සම යට ඇති මේද පටකය දේහ උෂ්ණත්වය පිටතට යාම වළක්වයි."),
    q("බිත්ති රහිත කුඩා රික්තකයක් ආහාර හෝ ජලය අල්ලා ගැනීමට භාවිත කරන ඒකසෛලික ජීවියා කවුද?", "ඇමීබා", "බැක්ටීරියා", "ක්ලැමිඩොමොනාස්", "වී සෛලය", "ඇමීබා ව්‍යාජ පාද මඟින් භක්ෂණයෙන් ආහාර ගනී."),
    q("පැරමීසියම් චලනය වීම සඳහා භාවිත කරන බාහිර ව්‍යුහ මොනවාද?", "පක්ෂ්ම (Cilia)", "කෂිකා (Flagella)", "ව්‍යාජ පාද", "නාල පාද", "පැරමීසියම් දේහය වටා කුඩා පක්ෂ්ම පිහිටා ඇත."),
    q("සියලුම සෛලීය ජීවීන්ගේ ජාන කේතය රඳා පවතින්නේ කුමන අණු තුළද?", "DNA", "ATP", "ග්ලූකෝස්", "කොලෙස්ටරෝල්", "DNA පරම්පරාවෙන් පරම්පරාවට ප්‍රවේණික ලක්ෂණ රැගෙන යයි."),
    q("වෛරසයක ප්‍රධාන ව්‍යුහමය කොටස් දෙක මොනවාද?", "ප්‍රෝටීන කොපුව හා න්‍යෂ්ටික අම්ල හරය", "සෛල බිත්තිය හා මයිටොකොන්ඩ්‍රියා", "ප්ලාස්ම පටලය හා රයිබොසෝම", "හරිතලවය හා න්‍යෂ්ටිය", "වෛරස අසෛලීය වේ."),
    q("ශාක පටකයක් සූක්ෂ්මදර්ශීව නිරීක්ෂණය කිරීමට සාමාන්‍යයෙන් යොදන වර්ණකයක් වන්නේ කුමක්ද?", "සැෆ්‍රනින්", "බෙනඩික්ට්", "ෆීනොප්තලීන්", "මෙතිල් ඔරේන්ජ්", "සැෆ්‍රනින් මඟින් ලිග්නීභූත සෛල බිත්ති රතු පැහැයට වර්ණ ගැන්වේ."),
    q("ජීවී දේහවල කැල්සියම් හොඳින් අවශෝෂණය වීමට හිරු එළිය ආධාරයෙන් සමේ නිපදවෙන විටමිනය කුමක්ද?", "විටමින් D", "විටමින් A", "විටමින් E", "විටමින් B₆", "උදෑසන හිරු එළිය විටමින් D සංස්ලේෂණයට උපකාරී වේ."),
    q("ග්ලයිකෝජන් සහ පිෂ්ඨය අතර ප්‍රධාන වෙනස්කම කුමක්ද?", "ග්ලයිකෝජන් සතුන්ගේ ද පිෂ්ඨය ශාකවල ද සංචිත වීම", "ග්ලයිකෝජන් ප්‍රෝටීනයක් වීම", "පිෂ්ඨය ඇමයිනෝ අම්ලවලින් සෑදීම", "ග්ලයිකෝජන් ජලයේ දිය නොවන අතර පිෂ්ඨය දියවීම", "දෙකම ග්ලූකෝස් බහුඅවයවික වුවත් හටගන්නා ජීවී කාණ්ඩ වෙනස් වේ."),
    q("ලූනු සිවියක සෛල අන්වීක්ෂයෙන් බලන විට එහි නොමැති ඉන්ද්‍රයිකාව කුමක්ද?", "හරිතලවය", "න්‍යෂ්ටිය", "සෛල බිත්තිය", "රික්තකය", "ලූනු බල්බයේ භූගත පත්‍ර සුදු පැහැති බැවින් හරිතලව නොමැත."),
    q("සජීවී සෛලවල ශක්ති ව්‍යවහාර මුදල (Energy currency) ලෙස හඳුන්වන අණුව කුමක්ද?", "ATP", "DNA", "NADPH", "ADP", "ඇඩිනොසීන් ට්‍රයිපොස්පේට් (ATP) සෛලීය ක්‍රියාවලට ක්ෂණික ශක්තිය සපයයි."),
    q("හිමොග්ලොබින්, ඉන්සියුලින් සහ කෙරටින් යන සියල්ල අයත් වන්නේ කුමන ජෛව අණු කාණ්ඩයටද?", "ප්‍රෝටීන", "කාබෝහයිඩ්‍රේට", "ලිපිඩ", "විටමින්", "මේවා විවිධ කෘත්‍ය ඉටු කරන ප්‍රෝටීන වර්ග වේ."),
    q("සමෙහි පිටතම ස්තරය වන අපිචර්මයේ ඇති ජල රෝධක ප්‍රෝටීනය කුමක්ද?", "කෙරටින්", "කොලැජන්", "මයෝසින්", "ඇල්බියුමින්", "හිසකෙස් හා නියපොතු ද කෙරටින්වලින් සෑදී ඇත."),
    q("ජීවීන්ගේ වර්ධනය, ප්‍රජනනය, චලනය, ශ්වසනය ආදී ලක්ෂණ අතරින් ශාක හා සතුන් අතර වඩාත් කැපී පෙනෙන වෙනසක් ඇත්තේ කුමකද?", "සංචරණය", "සෛලීය සංවිධානය", "ප්‍රජනනය", "ශ්වසනය", "සතුන්ට ස්ථානයෙන් ස්ථානයට යාමේ (සංචරණ) හැකියාව ඇත."),
    q("කුමන ප්‍රභාසංස්ලේෂී බැක්ටීරියා නිසා ආදි පෘථිවි වායුගෝලයට මුලින්ම ඔක්සිජන් එක් වී යැයි සැලකේද?", "සයනොබැක්ටීරියා", "ලැක්ටොබැසිලස්", "ඉ කෝලයි", "රයිසෝබියම්", "නීල හරිත ඇල්ගී හෙවත් සයනොබැක්ටීරියා හරිතප්‍රද දරයි."),
    q("කශිකාවක් මඟින් ජලයේ පිහිනා යන ඒකසෛලික හරිත ඇල්ගාවකට උදාහරණයක් වන්නේ කුමක්ද?", "ක්ලැමිඩොමොනාස්", "ස්පයිරොගයිරා", "ඇමීබා", "යීස්ට්", "ක්ලැමිඩොමොනාස් කෝප්ප හැඩැති හරිතලවයක් දරයි."),
    q("සුළඟින් රැගෙන යන බීජාණු මගින් නව ශාක බිහි කරන අතර හරිතප්‍රද නොමැති ජීවියෙකු වන්නේ කවුද?", "මියුකර් (පාන් පුස්)", "පොගොනේටම්", "සෙලැජිනෙල්ලා", "ස්පයිරොගයිරා", "මියුකර් දිලීර රාජධානියට අයත් වේ."),
    q("පැරණි සාම්ප්‍රදායික අත්දැකීම් අනුව ජීවීන් පූර්ණ ශාක හා සතුන් ලෙස දෙකට පමණක් වර්ග කළ විද්‍යාඥයා කවුද?", "ඇරිස්ටෝටල්", "විටේකර්", "ඩාවින්", "හුක්", "ප්‍රථම වරට විද්‍යාත්මක නොවූ කෘත්‍රිම වර්ගීකරණයක් ඇරිස්ටෝටල් සිදු කළේය."),
    q("රතු පැහැති ආලේපන හෝ ඖෂධ කර්මාන්තයේදී අමුද්‍රව්‍යයක් ලෙස යොදා ගන්නා ඒගාර් (Agar) ලබා ගන්නේ කුමන ජීවී කාණ්ඩයෙන්ද?", "රතු ඇල්ගී", "දුඹුරු ඇල්ගී", "බැක්ටීරියා", "දිලීර", "ඇල්ගී රාජධානි වර්ගීකරණයේදී ප්‍රොටිස්ටාවට අයත් වේ."),
    q("වකුටු හැඩැති සෛල හා පටක අතර හිස් අවකාශ පිරවීමට ඇති ලිහිල් සම්බන්ධක පටකය කුමක්ද?", "ඇරියෝලර් පටකය", "අස්ථි පටකය", "රුධිර පටකය", "ස්නායු පටකය", "ඇරියෝලර් පටකය සම පේශිවලට සම්බන්ධ කරයි."),
    q("අපිච්ඡද පටකවල සෛල පිහිටා ඇති සිහින් පටලමය පදනම හඳුන්වන්නේ කුමන නමින්ද?", "පාදම පටලය (Basement membrane)", "ටෝනොප්ලාස්ටය", "ප්ලාස්ම පටලය", "සෛල බිත්තිය", "පාදම පටලය අපිච්ඡද පටකය යටින් ඇති සම්බන්ධක පටකයට සවි කරයි."),
    q("ශ්වසන මාර්ගයේ දූවිලි හා ශ්ලේෂ්මල ඉහළට තල්ලු කිරීමට උපකාරී වන අපිච්ඡද පටකය කුමක්ද?", "පක්ෂ්මධර අපිච්ඡදය", "ශල්කමය අපිච්ඡදය", "ඝනකාභ අපිච්ඡදය", "සංයුක්ත අපිච්ඡදය", "ස්වාසනාලයේ පක්ෂ්ම නිරන්තරයෙන් චලනය වේ."),
    q("ගැමිට් (ජන්මාණු) සෑදීමේදී මව් සෛලයේ වර්ණදේහ සංඛ්‍යාව 2n = 16 ක් නම් එක් ජන්මාණුවක වර්ණදේහ කීයක් ඇත්ද?", "8", "16", "32", "4", "ඌනන විභාජනයෙන් වර්ණදේහ සංඛ්‍යාව අඩකින් අඩු වේ."),
    q("සෛලයක් අනූනන විභාජනයට පෙර DNA ප්‍රතිවලිත වීම සිදුවන්නේ කුමන අවධියේදීද?", "අන්තර් කලාව (Interphase)", "ප්‍රාක් කලාව", "යෝග කලාව", "වියෝග කලාව", "අන්තර් කලාවේදී සෛලය විභාජනය සඳහා සූදානම් වේ."),
    q("පාද හය බැගින් ඇති සහ ශරීරය හිස, උරස හා උදරය ලෙස බෙදුණු ආත්‍රොපෝඩා වර්ගය කුමක්ද?", "කෘමීන් (Insecta)", "මකුළුවන් (Arachnida)", "කකුළුවන් (Crustacea)", "හැකරැල්ලන් (Myriapoda)", "කෘමීන්ට පියාපත් යුගල දෙකක් හෝ එකක් ද තිබිය හැක."),
    q("පාද යුගල 4 ක් (පාද 8 ක්) ඇති සහ ස්පර්ශක නොමැති ආත්‍රොපෝඩා සත්වයා කවුද?", "මකුළුවා", "මැස්සා", "සමනලයා", "ඉස්සා", "ගෝනුස්සා සහ මකුළුවා ඇරක්නිඩා වර්ගයට අයත් වේ."),
    q("බීජ ඵලයක් තුළ ආවරණය වී පවතින සපුෂ්ප ශාක කාණ්ඩය කුමක්ද?", "ඇන්ජියොස්පර්ම්", "ජිම්නොස්පර්ම්", "ටෙරයිඩොෆයිටා", "බ්‍රයොෆයිටා", "මල් පිපෙන සියලු ශාක ආවෘත බීජක හෙවත් ඇන්ජියොස්පර්ම් වේ."),
    q("එන්සයිම ක්‍රියාකාරීත්වය කෙරෙහි බලපාන සාධකයක් නොවන්නේ කුමක්ද?", "ගුරුත්වාකර්ෂණය", "උෂ්ණත්වය", "pH අගය", "උපස්තර සාන්ද්‍රණය", "උෂ්ණත්වය හා pH අගය එන්සයිම ක්‍රියාකාරිත්වයට තදින් බලපායි."),
    q("මානව ඛේටයේ ඇති ඇමයිලේස් එන්සයිමය වඩාත් හොඳින් ක්‍රියා කරන ප්‍රශස්ත pH පරාසය කුමක්ද?", "pH 6.8–7.2 (උදාසීන ආසන්න)", "pH 1.5–2.0 (දැඩි ආම්ලික)", "pH 10.0–12.0 (දැඩි භාෂ්මික)", "pH 3.0–4.0 (ආම්ලික)", "ආමාශයේ පෙප්සින් pH 2 හිදී ක්‍රියා කරන අතර ඛේට ඇමයිලේස් උදාසීන pH අගයකදී ක්‍රියා කරයි."),
    q("මුහුදු පැළෑටි හෙවත් ඇල්ගී සහ ඒකසෛලික ජීවීන් අයත් වන රාජධානිය කුමක්ද?", "ප්‍රොටිස්ටා", "ප්ලාන්ටේ", "ෆන්ගයි", "මොනේරා", "බොහෝ ඇල්ගී වර්ග ප්‍රොටිස්ටා රාජධානිය යටතේ වර්ග කෙරේ."),
    q("පෘථිවිය මත වඩාත්ම සුලභ කාබනික සංයෝගය ලෙස සැලකෙන්නේ කුමක්ද?", "සෙලියුලෝස්", "ප්‍රෝටීන", "සුක්‍රෝස්", "DNA", "සියලුම ශාක සෛල බිත්ති සෙලියුලෝස්වලින් සෑදී ඇත."),
    q("සෛලයක සිදුවන පරිවෘත්තීය ක්‍රියාවලදී හටගන්නා විෂ සහිත හයිඩ්‍රජන් පෙරොක්සයිඩ් (H₂O₂) බිඳ දමන එන්සයිමය කුමක්ද?", "කැටලේස්", "ඇමයිලේස්", "ලයිපේස්", "පෙප්සින්", "අක්මා සෛලවල කැටලේස් එන්සයිමය H₂O₂ ජලය හා O₂ බවට පත් කරයි."),
    q("සාමාන්‍යයෙන් දෙමුහුන් සතුන් වන කොටළුවා (අශ්වයා හා බූරුවා අතර මුහුම) සරු නොවන්නේ ඇයි?", "වර්ණදේහ සංඛ්‍යා නොගැළපී ඌනනය අසාර්ථක වීමෙන්", "හෘදයේ කුටීර ගණන වෙනස් වීමෙන්", "පෙනහැලි නොමැති වීමෙන්", "ආහාර ජීර්ණය නොවීමෙන්", "විවිධ විශේෂ දෙකක් මුහුම් වූ විට සරු ජනිතයන් නොලැබේ."),
    q("ලෝහ ආලේපන හෝ ඖෂධ ඇසුරුම්වල දැකිය හැකි හරිත පැහැ ඇල්ගාවන් හා දිලීර අතර ඇති සහජීවී සම්බන්ධයෙන් සෑදෙන ජීවී ආකාරය කුමක්ද?", "ලයිකන (Lichens)", "මයිකොරයිසා", "කොරල්", "මූල ගැටිති", "ලයිකන වායු දූෂණය අඩු පිරිසිදු පරිසරවල හොඳින් වැඩේ."),
    q("බැක්ටීරියාවල ප්‍රජනනය බහුලවම සිදුවන අලිංගික ක්‍රමය කුමක්ද?", "ද්විඛණ්ඩනය", "අංකුරණය", "බීජාණු සෑදීම", "ලිංගික සංසේචනය", "හිතකර තත්ත්ව යටතේ බැක්ටීරියා මිනිත්තු 20 කට වරක් දෙකට බෙදේ."),
    q("කවචයක් නොමැති මොලුස්කා වංශයේ දක්ෂ පිහිනුම්කරුවෙකු වන සත්වයා කවුද?", "දැල්ලා", "ගොළුබෙල්ලා", "හම්බෙල්ලා", "කිතුල් බෙල්ලා", "දැල්ලා සහ බූවල්ලා තුළ බාහිර කවචයක් නොමැත."),
    q("ශාක පත්‍ර මත දිලීර හා බැක්ටීරියා පැතිරීම පාලනය කරන දිලීර නාශකවල හෝ ප්‍රතිජීවක නිපදවීමට මුලින්ම යොදා ගත් දිලීරය කුමක්ද?", "පෙනිසිලියම්", "යීස්ට්", "මියුකර්", "ඇගැරිකස්", "ඇලෙක්සැන්ඩර් ෆ්ලෙමින් පෙනිසිලියම් දිලීරයෙන් පෙනිසිලින් සොයා ගත්තේය."),
    q("ජීවීන් සතු පොදු ලක්ෂණයක් නොවන්නේ කුමක්ද?", "ප්‍රභාසංස්ලේෂණය කිරීම", "සෛලීය සංවිධානය", "උද්දීප්‍යතාව", "වර්ධනය හා විකසනය", "ප්‍රභාසංස්ලේෂණය සිදු කරන්නේ හරිත ශාක හා සමහර බැක්ටීරියා/ඇල්ගී පමණි."),
    q("දේහයේ ජලය අධික ලෙස ඉවත් වීම නිසා පටකවල ඇතිවන අසාමාන්‍ය තත්ත්වය හඳුන්වන්නේ කෙසේද?", "විජලනය", "ආස්‍රැතිය", "උත්ස්වේදනය", "ප්ලාස්ම විච්ඡේදනය", "අධික පාචනය හා වමනය නිසා විජලනය ඇති විය හැක."),
    q("ප්‍රෝටීන ද්‍රාවණයක් අධික අම්ලයක් හෝ බැර ලෝහ ලවණයක් සමඟ මිශ්‍ර කළ විට කැටි ගැසීම හඳුන්වන්නේ කෙසේද?", "දුස්ස්වභාවීකරණය", "සංඝනීභවනය", "ජලවිච්ඡේදනය", "කැටිකිරීම", "බිත්තර සුදු මදය තැම්බීමේදී ඇල්බියුමින් ප්‍රෝටීනය දුස්ස්වභාවීකරණය වේ."),
    q("ලෝකයේ සිටින සියලුම ජීවීන්ගේ වර්ණදේහවල අඩංගු ප්‍රධාන ස්වභාවික භෂ්ම හතරෙන් එකක් නොවන්නේ කුමක්ද?", "යුරේනියම්", "ඇඩිනීන්", "ගුවැනීන්", "සයිටොසීන්", "යුරේනියම් යනු විකිරණශීලී රසායනික මූලද්‍රව්‍යයකි."),
    q("රතු රුධිරාණු ඉසො-තානික (සම-තානික) ද්‍රාවණයක තැබූ විට සිදුවන්නේ කුමක්ද?", "සෛලයේ හැඩයේ වෙනසක් සිදු නොවීම", "සෛල පුපුරා යාම", "සෛල හැකිලී යාම", "න්‍යෂ්ටිය අතුරුදහන් වීම", "ද්‍රාවණ දෙකේම ජල විභවය සමාන බැවින් ශුද්ධ ජල චලනයක් නැත."),
    q("ශාක සෛලයක් ආස්‍රැත ජලයේ (අධෝ-තානික) තැබූ විට එය නොපිපිරී තද වී පවතින්නේ කුමක් නිසාද?", "දෘඪ සෛල බිත්තිය මඟින් ප්‍රතිරෝධයක් දැක්වීම", "ප්ලාස්ම පටලය ජලය ඇතුළු නොකිරීම", "රික්තකය හැකිලීම", "හරිතලව ජලය උරා ගැනීම", "සෛල බිත්තියේ බිත්ති පීඩනය නිසා සෛලය ශූන තත්ත්වයට පත්වේ."),
    q("පහත දැක්වෙන පොලිසැකරයිඩ අතරින් අත්‍යවශ්‍යයෙන්ම ශාක පත්‍ර හා බීජවල ප්‍රධාන සංචිත ආහාරය කුමක්ද?", "පිෂ්ඨය", "ග්ලයිකෝජන්", "සෙලියුලෝස්", "කයිටින්", "ශාක ආහාර පිෂ්ඨ කණිකා ලෙස ගබඩා කරයි."),
    q("අන්වීක්ෂයෙන් නිරීක්ෂණය කිරීමේදී ආලෝක කදම්බය වස්තුව වෙත නාභිගත කිරීමට භාවිත කරන කොටස කුමක්ද?", "කන්ඩෙන්සරය හා දර්පණය", "උපනෙත", "සියුම් සීරුමාරු ඇණය", "වේදිකාව", "දර්පණය ආලෝකය ඉහළට පරාවර්තනය කරයි."),
    q("පක්ෂීන් සහ උරගයින් දෙවර්ගයේම දැකිය හැකි පොදු ලක්ෂණයක් වන්නේ කුමක්ද?", "කවච සහිත බිත්තර දැමීම", "සිව් කුටීර හෘදයක් තිබීම", "අචලතාපී වීම", "පිහාටු තිබීම", "දෙවර්ගයම අණ්ඩජ සතුන් වන අතර අභ්‍යන්තර සංසේචනය පෙන්වයි."),
    q("උභයජීවීන්ගේ ජීවන චක්‍රයේ ඉස්ගෙඩියා අවධියේදී ශ්වසනය සිදු කරන අවයවය කුමක්ද?", "කරමල්", "පෙනහැලි", "මුඛ කුහරය", "සම පමණි", "ජලජ ඉස්ගෙඩියන් බාහිර හා අභ්‍යන්තර කරමල් මඟින් හුස්ම ගනී."),
    q("තල්මසා මත්ස්‍යයෙකු නොවී ක්ෂීරපායී සත්වයෙකු ලෙස වර්ග කිරීමට ප්‍රධාන හේතුව කුමක්ද?", "පැටවුන් බිහි කර කිරි දීම හා පෙනහැලි තිබීම", "ජලයේ පිහිනීම", "වරල් පිහිටීම", "විශාල ශරීරයක් තිබීම", "තල්මසාට කරමල් නොමැති අතර වාතය ආශ්වාස කරයි."),
    q("ඒකසෛලික ජීවියෙකු තුළ ශ්වසනය, පෝෂණය සහ බහිස්ස්‍රාවය යන සියලු කෘත්‍ය ඉටු වන්නේ කෙසේද?", "එම තනි සෛලය තුළමය", "විශේෂිත පටක මඟිනි", "අවයව පද්ධති මඟිනි", "රුධිර සංසරණය මඟිනි", "ඒකසෛලික ජීවියෙකු ස්වාධීන සම්පූර්ණ ජීවියෙකි."),
    q("දේහයේ කැඩුණු අස්ථි හෝ තුවාල වූ සම ඉක්මනින් සුව වීම සඳහා අත්‍යවශ්‍ය වන විභාජන ක්‍රමය කුමක්ද?", "අනූනනය", "ඌනනය", "අංකුරණය", "විඛණ්ඩනය", "අනූනන විභාජනය මඟින් ජානමය වශයෙන් සමාන නව සෛල නිපදවේ."),
    q("පත්‍ර වර්ණක පරීක්ෂාවේදී ආහාර වර්ග හඳුනාගැනීමේදී තෙල් පැල්ලම් පරීක්ෂාව සඳහා භාවිත කරන්නේ කුමක්ද?", "සුදු කඩදාසියක්", "නිල් ලිට්මස්", "අයඩින් ද්‍රාවණය", "හුණු දියර", "ලිපිඩ කඩදාසි මත පාරභාසක තෙල් පැල්ලමක් ඇති කරයි."),
    q("ශාකමය ආහාරයක් වන නමුත් සම්පූර්ණ ප්‍රෝටීන ගුණයට ආසන්න ප්‍රෝටීන සපයන ධාන්‍ය හා රනිල සංයෝජනයකට උදාහරණය කුමක්ද?", "බත් සහ පරිප්පු", "පාන් සහ බටර්", "අල සහ සීනි", "කෙසෙල් සහ මීපැණි", "ධාන්‍ය හා රනිල එක්ව ආහාරයට ගැනීමෙන් සියලුම අත්‍යවශ්‍ය ඇමයිනෝ අම්ල ලැබේ."),
    q("විටමින් E (ටොකොෆෙරෝල්) හි ප්‍රධාන ජීව විද්‍යාත්මක කාර්යය කුමක්ද?", "සෛල පටල ආරක්ෂා කරන ප්‍රතිඔක්සිකාරකයක් වීම", "ඇසේ දෘෂ්ටි වර්ණක තැනීම", "රුධිරය කැටි ගැස්වීම", "දත් එනැමලය තැනීම", "විටමින් E ශාක තෙල් හා ඇට වර්ගවල බහුලය.")
  )
}
